using Microsoft.Extensions.Logging;

namespace Valora.Application.Benchmarks;

internal static class BenchmarkGuard { public static void Organization(Guid id){if(id==Guid.Empty)throw new ArgumentException("Selecione uma organização antes de continuar.");} public static void User(Guid id){if(id==Guid.Empty)throw new ArgumentException("Usuário autenticado não identificado.");} public static void Period(DateOnly start,DateOnly end){if(start==default||end==default||end<start)throw new ArgumentException("Informe um período válido para a comparação.");} }
public sealed class BenchmarkCohortService(IBenchmarkCohortRepository repository,ILogger<BenchmarkCohortService> logger) { public Task<IReadOnlyList<BenchmarkCohortDto>> List(Guid o,CancellationToken ct){BenchmarkGuard.Organization(o);return repository.List(o,ct);} public async Task<Guid> Create(Guid o,Guid u,CreateBenchmarkCohortRequest r,CancellationToken ct){BenchmarkGuard.Organization(o);BenchmarkGuard.User(u);if(r.MinimumSampleSize<5)throw new ArgumentException("A amostra mínima deve preservar k-anonymity (k ≥ 5).");var id=await repository.Create(o,u,r,ct);logger.LogInformation("Benchmark cohort created. OrganizationId={OrganizationId} CohortId={CohortId}",o,id);return id;} }
public sealed class BenchmarkSnapshotService(IBenchmarkSnapshotRepository repository,ILogger<BenchmarkSnapshotService> logger) { public Task<IReadOnlyList<BenchmarkSnapshotDto>> List(Guid o,CancellationToken ct){BenchmarkGuard.Organization(o);return repository.List(o,ct);} public async Task<Guid> Generate(Guid o,Guid u,GenerateBenchmarkSnapshotRequest r,CancellationToken ct){BenchmarkGuard.Organization(o);BenchmarkGuard.User(u);BenchmarkGuard.Period(r.PeriodStart,r.PeriodEnd);var id=await repository.Create(o,u,r,ct);logger.LogInformation("benchmark.snapshot.generated OrganizationId={OrganizationId} SnapshotId={SnapshotId}",o,id);return id;} }
public sealed class BenchmarkPrivacyService(IBenchmarkPrivacyRepository repository,ILogger<BenchmarkPrivacyService> logger) { public Task<BenchmarkPrivacyRuleDto> Get(Guid o,CancellationToken ct){BenchmarkGuard.Organization(o);return repository.Get(o,ct);} public async Task<bool> CanDisplay(Guid o,Guid u,int sampleSize,CancellationToken ct){var rule=await Get(o,ct);var minimum=Math.Max(5,Math.Max(rule.MinimumSampleSize,rule.KAnonymity));if(rule.Status!="active"||sampleSize<minimum){var reason=$"Comparação suprimida: amostra {sampleSize}, mínimo {minimum}.";await repository.AuditBlocked(o,u,reason,ct);logger.LogWarning("benchmark.privacy.blocked OrganizationId={OrganizationId} Reason={Reason}",o,reason);return false;}return true;} }
public sealed class BenchmarkComparisonService(IBenchmarkComparisonRepository comparisons,IBenchmarkMetricRepository metrics,BenchmarkPrivacyService privacy,ILogger<BenchmarkComparisonService> logger) { public async Task<BenchmarkComparisonDto> Compare(Guid o,Guid u,BenchmarkComparisonRequest r,CancellationToken ct){BenchmarkGuard.Organization(o);BenchmarkGuard.User(u);BenchmarkGuard.Period(r.PeriodStart,r.PeriodEnd);if(string.IsNullOrWhiteSpace(r.Segment)||string.IsNullOrWhiteSpace(r.Criterion))throw new ArgumentException("Segmento e critério são obrigatórios.");if(r.ComparisonType=="cohort"&&r.CohortId is null)throw new ArgumentException("Selecione uma coorte anônima.");var id=await comparisons.CreateRequest(o,u,r,ct);var values=await metrics.Compare(o,id,r,ct);var sample=values.Count==0?0:values.Min(x=>x.SampleSize);var available=await privacy.CanDisplay(o,u,sample,ct);var limitations=new List<string>();if(!available)limitations.Add("Amostra insuficiente ou risco de reidentificação; valores agregados foram ocultados.");if(values.Any(x=>x.ConfidenceLevel!="high"))limitations.Add("A confiança varia conforme cobertura, atualidade e qualidade das fontes.");limitations.Add("Diferenças observadas não comprovam causalidade; a decisão humana deve considerar o contexto.");var confidence=available?(values.All(x=>x.ConfidenceLevel=="high")?"high":"medium"):"unavailable";await comparisons.Complete(o,id,available,confidence,sample,limitations,ct);logger.LogInformation("benchmark.comparison.requested OrganizationId={OrganizationId} ComparisonId={ComparisonId} Available={Available}",o,id,available);return (await comparisons.Get(o,id,ct))!;} }
public sealed class BenchmarkInsightService(IBenchmarkInsightRepository repository,ILogger<BenchmarkInsightService> logger) { public Task<IReadOnlyList<BenchmarkInsightDto>> List(Guid o,CancellationToken ct){BenchmarkGuard.Organization(o);return repository.List(o,ct);} public async Task<Guid> ConvertToAction(Guid o,Guid id,Guid u,CancellationToken ct){BenchmarkGuard.Organization(o);BenchmarkGuard.User(u);var action=await repository.ConvertToAction(o,id,u,ct);logger.LogInformation("benchmark.insight.converted_to_action OrganizationId={OrganizationId} InsightId={InsightId} ActionId={ActionId}",o,id,action);return action;} }
public sealed class BenchmarkExportService(IBenchmarkExportRepository repository,ILogger<BenchmarkExportService> logger) { public async Task<Guid> Export(Guid o,Guid u,BenchmarkExportRequest r,CancellationToken ct){BenchmarkGuard.Organization(o);BenchmarkGuard.User(u);var id=await repository.Create(o,u,r,ct);logger.LogInformation("benchmark.export.generated OrganizationId={OrganizationId} ExportId={ExportId}",o,id);return id;} }
